/**
 * ChannelManagerAPI.js
 * 
 * Abstraction layer for connecting to Channel Managers (like Channex, SiteMinder).
 * Standardizes the flow of pushing rates, availability, and pulling reservations.
 */

class ChannelManagerAPI {
  constructor(apiKey, propertyId, isMockMode = true) {
    this.apiKey = apiKey;
    this.propertyId = propertyId;
    this.isMockMode = isMockMode;
    this.baseUrl = "https://staging.channex.io/api/v1"; // Channex API endpoint
  }

  /**
   * Pushes new pricing rates generated by AI to the OTA channels.
   * @param {Array} rates - Array of objects: { room_code, date, rate }
   */
  async pushRates(rates) {
    if (this.isMockMode) {
      console.log(`[MOCK ChannelManager] Pushing rates for ${this.propertyId}:`, rates);
      return new Promise(resolve => setTimeout(() => resolve({ success: true, mocked: true }), 800));
    }

    try {
      const response = await fetch(`${this.baseUrl}/updates`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'user-api-key': this.apiKey
        },
        body: JSON.stringify({
          values: rates.map(r => ({
            property_id: this.propertyId,
            room_type_id: r.room_code,
            date_from: r.date,
            date_to: r.date,
            rate: r.rate
          }))
        })
      });
      if (!response.ok) throw new Error("Failed to push rates to OTA");
      return await response.json();
    } catch (err) {
      console.error("ChannelManager pushRates error:", err);
      throw err;
    }
  }

  /**
   * Pulls new reservations from OTAs (Booking.com, Expedia, etc.)
   */
  async pullReservations() {
    if (this.isMockMode) {
      console.log(`[MOCK ChannelManager] Pulling reservations for ${this.propertyId}`);
      return new Promise(resolve => setTimeout(() => {
        resolve({
          success: true,
          mocked: true,
          data: [
            {
              ota_reservation_id: `BKG-${Math.floor(Math.random() * 90000)}`,
              channel_source: 'Booking.com',
              guest_name: 'Alex Johnson',
              guest_email: 'alex.j@example.com',
              guest_phone: '+1 555-0192',
              room_type: 'Standard Room',
              check_in: new Date(Date.now() + 86400000 * 2).toISOString().split('T')[0],
              check_out: new Date(Date.now() + 86400000 * 5).toISOString().split('T')[0],
              nights: 3,
              total_amount: 450.00,
              channel_commission: 67.50,
              status: 'Confirmed'
            },
            {
              ota_reservation_id: `EXP-${Math.floor(Math.random() * 90000)}`,
              channel_source: 'Expedia',
              guest_name: 'Sarah Connor',
              guest_email: 's.connor@example.com',
              guest_phone: '+1 555-0991',
              room_type: 'Deluxe Room',
              check_in: new Date(Date.now() + 86400000 * 4).toISOString().split('T')[0],
              check_out: new Date(Date.now() + 86400000 * 6).toISOString().split('T')[0],
              nights: 2,
              total_amount: 380.00,
              channel_commission: 57.00,
              status: 'Confirmed'
            }
          ]
        });
      }, 1500));
    }

    try {
      const response = await fetch(`${this.baseUrl}/bookings?property_id=${this.propertyId}&status=new`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'user-api-key': this.apiKey
        }
      });
      if (!response.ok) throw new Error("Failed to pull reservations from OTA");
      return await response.json();
    } catch (err) {
      console.error("ChannelManager pullReservations error:", err);
      throw err;
    }
  }

  /**
   * Pushes availability blocks to OTAs.
   */
  async pushAvailability(roomCode, dateFrom, dateTo, available) {
    if (this.isMockMode) {
      console.log(`[MOCK ChannelManager] Pushing availability for ${roomCode}: ${available} available from ${dateFrom} to ${dateTo}`);
      return new Promise(resolve => setTimeout(() => resolve({ success: true, mocked: true }), 500));
    }

    try {
      const response = await fetch(`${this.baseUrl}/updates`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'user-api-key': this.apiKey
        },
        body: JSON.stringify({
          values: [{
            property_id: this.propertyId,
            room_type_id: roomCode,
            date_from: dateFrom,
            date_to: dateTo,
            availability: available
          }]
        })
      });
      if (!response.ok) throw new Error("Failed to push availability to OTA");
      return await response.json();
    } catch (err) {
      console.error("ChannelManager pushAvailability error:", err);
      throw err;
    }
  }
}

export default ChannelManagerAPI;
